mapper.select:
select bb.bill_id billId, be.employee_name employeeName, DATE_FORMAT(bb.order_date, '%Y-%m-%d %H:%i:%s') orderDate, bb.order_num orderNum, bp.name, bp.mobile, IFNULL(bb.privilege_amount + bb.actual_amount,0) originalPrice, IFNULL(bb.privilege_amount,0) privilegeAmount, IFNULL(bb.actual_amount,0) actualAmount, IFNULL(bb.received_amount,0) receivedAmount, IFNULL(bb.debt_amount,0) debtAmount from base_bill bb join base_patient bp on bp.patient_id = bb.patient_id join base_treatment_process btpr on btpr.patient_id = bp.patient_id join base_employee be on btpr.registered_dentist_id = be.user_id
AND bb.org_id = #{form.orgId}
and DATE_FORMAT(bb.order_date, "%Y-%m-%d") >= DATE_FORMAT(#{form.startDate}, "%Y-%m-%d") and DATE_FORMAT(bb.order_date, "%Y-%m-%d") <= DATE_FORMAT(#{form.endDate}, "%Y-%m-%d")
AND btpr.registered_dentist_id in
#{registeredDentistId}
AND bp.patient_id in
#{ids}
group by bb.order_date asc

SELECT bor.orderDate, bor.billId, bor.orderNum, bor.billNum, bor.patientId, bor.patientName, bor.mobile, bor.gender, bor.regDentistId, bor.regDentistName, IFNULL(bor.orderAmount,0) orderAmount, IFNULL(bor.privilegeAmount,0) privilegeAmount, IFNULL(bor.actualAmount,0) actualAmount, IFNULL(bor.receivedAmount,0) receivedAmount, bor.chargeStatus, bor.billerId, bor.biller FROM ( SELECT bb.org_id as orgId, DATE_FORMAT( bb.order_date, '%Y-%m-%d' ) AS orderDate, bb.bill_id AS billId, bb.order_num AS orderNum, bb.bill_num AS billNum, bb.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile AS mobile, bp.gender AS gender, btp.registered_dentist_id AS regDentistId, btp.employee_name AS regDentistName, bb.order_amount AS orderAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS receivedAmount, IF ( bb.bill_num = NULL OR '', 0, 1 ) AS chargeStatus, bb.biller_id AS billerId, be.employee_name AS biller FROM base_bill bb LEFT JOIN ( SELECT btp.treatment_id, btp.registered_dentist_id, be.employee_name FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) btp ON bb.treatment_id = btp.treatment_id LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN base_employee be ON bb.biller_id = be.user_id ) bor
and bor.orgId = #{query.orgId}
and bor.orderNum like concat('%', #{query.orderNum} ,'%')
and bor.billNum like concat('%', #{query.billNum} ,'%')
and concat(IFNULL(bor.patientName, ''), IFNULL(bor.pinyinName, ''), IFNULL(bor.mobile, '')) like concat('%', #{query.keyWord}, '%')
and bor.orderDate >= #{query.orderStartDate}
and bor.orderDate <= #{query.orderEndDate}
and bor.regDentistId in
#{item}
ORDER BY bor.orderDate DESC

SELECT bpr.billId, DATE_FORMAT(bpr.orderDate, '%Y-%m-%d') orderDate, bpr.billNum, bpr.orgId, bpr.orgName, bpr.patientId, bpr.patientName, bpr.mobile, bpr.regDentistId, bpr.regDentistName, IFNULL(bpr.originalAmount,0) originalAmount, IFNULL(bpr.discountAmount,0) discountAmount, IFNULL(bpr.actualAmount,0) actualAmount, bpr.privilegeType, bpr.payeeId, bpr.payeeName FROM ( SELECT bb.bill_id AS billId, bb.order_date AS orderDate, bb.bill_num AS billNum, bb.org_id AS orgId, bo.abbreviation AS orgName, bb.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile AS mobile, btp.registered_dentist_id AS regDentistId, btp.employee_name AS regDentistName, bb.order_amount AS originalAmount, bb.privilege_amount AS discountAmount, bb.actual_amount AS actualAmount, bb.privilege_type AS privilegeType, bbp.payee_user_id AS payeeId, bbp.employee_name AS payeeName FROM base_bill bb LEFT JOIN base_organization bo ON bb.org_id = bo.org_id LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN ( SELECT btp.registered_dentist_id, btp.treatment_id, be.employee_name FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) btp ON bb.treatment_id = btp.treatment_id LEFT JOIN ( SELECT bbp.bill_id, bbp.payee_user_id, be.employee_name FROM base_bill_pay bbp LEFT JOIN base_employee be ON bbp.payee_user_id = be.user_id ) bbp ON bb.bill_id = bbp.bill_id ) bpr
and concat(IFNULL(bpr.patientName, ''), IFNULL(bpr.pinyinName, ''), IFNULL(bpr.mobile, '')) like concat('%', #{query.keyWord}, '%')
and bpr.billNum like concat('%', #{query.billNum} ,'%')
and bpr.orgId in
#{item}
and bpr.orderDate >= #{query.orderStartDate}
and bpr.orderDate <= #{query.orderEndDate}
and bpr.regDentistId in
#{item}
and bpr.privilegeType in
#{item}

SELECT billId, orgId, DATE_FORMAT(orderDate, '%Y-%m-%d') orderDate, billNum, patientId, patientName, mobile, regDentistId, regDentistName, IFNULL(totalOriginalAmount,0) totalOriginalAmount, IFNULL(totalActualAmount,0) totalActualAmount, IFNULL(billReceivableAmount,0) billReceivableAmount FROM ( SELECT bb.bill_id AS billId, bb.org_id as orgId, bb.order_date AS orderDate, bb.bill_num AS billNum, bb.patient_id AS patientId, btp.`name` AS patientName, btp.pinyin_name as pinyinName, btp.mobile, btp.registered_dentist_id AS regDentistId, btp.employee_name AS regDentistName, bb.order_amount AS totalOriginalAmount, bb.actual_amount AS totalActualAmount, bb.received_amount AS billReceivableAmount FROM base_bill bb LEFT JOIN ( SELECT btp.treatment_id, btp.patient_id, bp.`name`, bp.mobile, bp.gender, bp.pinyin_name, btp.registered_dentist_id, be.employee_name FROM base_treatment_process btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treatment_id IS NOT NULL GROUP BY btp.treatment_id ) btp ON bb.treatment_id = btp.treatment_id ) brr
and brr.orgId = #{query.orgId}
and brr.orderDate = #{query.orderDate}
and concat(IFNULL(brr.patientName, ''), IFNULL(brr.pinyinName, ''), IFNULL(brr.mobile, '')) like concat('%', #{query.keyword}, '%')
and brr.regDentistId in
#{item}

SELECT SUM( bb.totalOriginalAmount ) AS totalOriginalAmount, SUM( bb.totalActualReceiveAmount ) AS totalActualReceiveAmount, SUM( bb.totalDiscountAmount ) AS totalDiscountAmount, SUM( bb.totalDebtAmount ) AS totalDebtAmount FROM ( SELECT bb.org_id, SUM( bb.order_amount ) AS totalOriginalAmount, SUM( bb.privilege_amount ) AS totalDiscountAmount, SUM( bb.actual_amount ) AS totalActualReceiveAmount, SUM( bb.debt_amount ) AS totalDebtAmount FROM base_bill bb
AND bb.bill_num IS NOT NULL
and DATE_FORMAT( bb.bill_date, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT( bb.bill_date, '%Y') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y') <= #{query.endDate}
GROUP BY bb.org_id ) bb
and bb.org_id in
#{item}
